import React, { useEffect, useState } from 'react';
import {
  acceptHandover,
  acknowledgeHandover,
  cancelLeaveRequest,
  createLeaveRequest,
  decideLeaveRequest,
  declineHandover,
  getLeaveOverview,
  getPendingLeaveRequests,
} from '../services/leaveApi';
import { deleteProfilePhoto, updateProfile, uploadProfilePhoto } from '../services/profileApi';
import { getChatMessages, getChatUsers, sendChatMessage } from '../services/chatApi';
import './LeaveDashboard.css';
import AppShell from './AppShell';

const emptyForm = {
  leave_type_id: '', start_date: '', end_date: '', reason: '', contact_phone: '', contact_email: '',
  address_line1: '', address_line2: '', city: '', country: 'Kenya', postal_code: '', handover_user_id: '', handover_report: '',
};
const handoverStatement = 'I have been briefed on the work to be undertaken and hereby agree to take responsibility of the work to be executed.';

const formatDate = (value) => {
  if (!value) return '-';
  return new Date(`${value}T00:00:00`).toLocaleDateString(undefined, {
    day: 'numeric', month: 'short', year: 'numeric',
  });
};

const statusClass = (status) => `leave-status leave-status-${String(status).toLowerCase()}`;

const LeaveDashboard = ({ currentUser, onUserUpdated, handleLogout }) => {
  const [overview, setOverview] = useState({ types: [], balances: [], requests: [] });
  const [pendingRequests, setPendingRequests] = useState([]);
  const [form, setForm] = useState(emptyForm);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [message, setMessage] = useState(null);
  const [showRequestForm, setShowRequestForm] = useState(false);
  const [showProfile, setShowProfile] = useState(false);
  const [profileForm, setProfileForm] = useState({});
  const [profilePhoto, setProfilePhoto] = useState('');
  const [chatUsers, setChatUsers] = useState([]);
  const [chatPeer, setChatPeer] = useState('');
  const [chatMessages, setChatMessages] = useState([]);
  const [chatBody, setChatBody] = useState('');
  const [showChat, setShowChat] = useState(false);

  const canApprove = ['manager', 'hr_admin'].includes(currentUser?.role);

  const loadData = async () => {
    setLoading(true);
    setMessage(null);
    try {
      const [data, chatData] = await Promise.all([
        getLeaveOverview(),
        getChatUsers().catch(() => ({ data: [] })),
      ]);
      setOverview(data);
      setChatUsers(chatData.data || []);
      if (!chatPeer && (chatData.data || []).length > 0) {
        setChatPeer(String((chatData.data || [])[0].id));
      }
      if (canApprove) {
        try {
          const pending = await getPendingLeaveRequests();
          setPendingRequests(pending.data || []);
        } catch (error) {
          if (!error.message.toLowerCase().includes('forbidden')) throw error;
        }
      }
    } catch (error) {
      setMessage({ type: 'error', text: error.message });
    } finally {
      setLoading(false);
    }
  };

  // The initial load intentionally runs once for the authenticated user.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { loadData(); }, []);

  const updateForm = (event) => {
    const { name, value } = event.target;
    setForm((current) => ({ ...current, [name]: value }));
  };

  const workingDays = () => {
    if (!form.start_date || !form.end_date) return 0;
    const start = new Date(`${form.start_date}T00:00:00`);
    const end = new Date(`${form.end_date}T00:00:00`);
    if (end < start) return 0;
    let days = 0;
    for (let current = start; current <= end; current.setDate(current.getDate() + 1)) {
      if (current.getDay() !== 0 && current.getDay() !== 6) days += 1;
    }
    return days;
  };

  const openProfile = () => {
    setProfileForm({
      employee_name: currentUser.employee_name || currentUser.full_name || '',
      job_position_title: currentUser.job_position_title || '', employer: currentUser.employer || '',
      department: currentUser.department || '', contact_phone: currentUser.contact?.phone || '',
      contact_email: currentUser.contact?.email || '', address_line1: currentUser.contact?.address_line1 || '',
      address_line2: currentUser.contact?.address_line2 || '', city: currentUser.contact?.city || '',
      country: currentUser.contact?.country || 'Kenya', postal_code: currentUser.contact?.postal_code || '',
    });
    setProfilePhoto(currentUser.profile_photo_url || '');
    setShowProfile(true);
  };

  const saveProfile = async (event) => {
    event.preventDefault();
    try {
      const user = await updateProfile({ ...profileForm, profile_photo_url: profilePhoto || null });
      onUserUpdated(user);
      setShowProfile(false);
      setMessage({ type: 'success', text: 'Profile updated.' });
    } catch (error) { setMessage({ type: 'error', text: error.message }); }
  };

  const changeProfilePhoto = async (event) => {
    const file = event.target.files?.[0];
    if (!file) return;
    try {
      const user = await uploadProfilePhoto(file);
      onUserUpdated(user);
      setProfilePhoto(user.profile_photo_url || '');
      setMessage({ type: 'success', text: 'Profile photo updated.' });
    } catch (error) {
      setMessage({ type: 'error', text: error.message });
    }
  };

  const removeProfilePhoto = async () => {
    try {
      const user = await deleteProfilePhoto();
      onUserUpdated(user);
      setProfilePhoto('');
      setMessage({ type: 'success', text: 'Profile photo removed.' });
    } catch (error) {
      setMessage({ type: 'error', text: error.message });
    }
  };

  const loadChat = async () => {
    try {
      const users = await getChatUsers();
      setChatUsers(users.data || []);
      if (!chatPeer && users.data?.[0]) setChatPeer(String(users.data[0].id));
    } catch (error) { setMessage({ type: 'error', text: error.message }); }
  };

  // Chat is loaded when the panel opens; the authenticated user remains stable for this view.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => { if (showChat) loadChat(); }, [showChat]);
  useEffect(() => {
    if (!showChat || !chatPeer) return undefined;
    getChatMessages(chatPeer).then((data) => setChatMessages(data.data || [])).catch(() => {});
    return undefined;
  }, [showChat, chatPeer]);

  const submitChat = async (event) => {
    event.preventDefault();
    if (!chatBody.trim() || !chatPeer) return;
    try {
      await sendChatMessage(Number(chatPeer), chatBody.trim());
      setChatBody('');
      const data = await getChatMessages(chatPeer);
      setChatMessages(data.data || []);
    } catch (error) { setMessage({ type: 'error', text: error.message }); }
  };

  const submitRequest = async (event) => {
    event.preventDefault();
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(form.contact_email.trim())) {
      setMessage({ type: 'error', text: 'Enter a valid leave contact email address.' });
      return;
    }
    if (!/^\+?[0-9 ()-]{7,30}$/.test(form.contact_phone.trim())) {
      setMessage({ type: 'error', text: 'Enter a valid leave contact phone number.' });
      return;
    }
    setSubmitting(true);
    setMessage(null);
    try {
      await createLeaveRequest({ ...form, leave_type_id: Number(form.leave_type_id), handover_user_id: form.handover_user_id ? Number(form.handover_user_id) : null });
      setForm(emptyForm);
      setShowRequestForm(false);
      setMessage({ type: 'success', text: 'Leave request submitted for approval.' });
      await loadData();
    } catch (error) {
      setMessage({ type: 'error', text: error.message });
    } finally {
      setSubmitting(false);
    }
  };

  const cancelRequest = async (requestId) => {
    try {
      await cancelLeaveRequest(requestId);
      setMessage({ type: 'success', text: 'Leave request cancelled.' });
      await loadData();
    } catch (error) {
      setMessage({ type: 'error', text: error.message });
    }
  };

  const decideRequest = async (requestId, decision) => {
    const decisionComment = window.prompt(`Comment for ${decision} (optional):`, '') ?? '';
    if (decision === 'reject' && !decisionComment.trim()) {
      setMessage({ type: 'error', text: 'A comment is required when rejecting a request.' });
      return;
    }
    try {
      await decideLeaveRequest(requestId, decision, decisionComment);
      setMessage({ type: 'success', text: `Leave request ${decision}d.` });
      await loadData();
    } catch (error) {
      setMessage({ type: 'error', text: error.message });
    }
  };

  const acknowledge = async (requestId) => {
    try {
      await acknowledgeHandover(requestId, currentUser.name || currentUser.full_name, handoverStatement);
      setMessage({ type: 'success', text: 'Handover acknowledged.' });
      await loadData();
    } catch (error) { setMessage({ type: 'error', text: error.message }); }
  };

  const acceptHandoverRequest = async (requestId) => {
    try {
      await acceptHandover(requestId, handoverStatement);
      setMessage({ type: 'success', text: 'Handover accepted.' });
      await loadData();
    } catch (error) { setMessage({ type: 'error', text: error.message }); }
  };

  const declineHandoverRequest = async (requestId) => {
    try {
      const reason = window.prompt('Why are you declining the handover?', 'Unable to take on this work at the moment.') || 'Unable to take on this work at the moment.';
      await declineHandover(requestId, reason);
      setMessage({ type: 'success', text: 'Handover declined.' });
      await loadData();
    } catch (error) { setMessage({ type: 'error', text: error.message }); }
  };

  const pendingCount = overview.requests.filter((request) => request.status === 'pending').length;
  const usedDays = overview.balances.reduce((sum, balance) => sum + Number(balance.used_days || 0), 0);
  const availableDays = overview.balances.reduce((sum, balance) => sum + Number(balance.available_days || 0), 0);
  const leaveTypeName = (request) => overview.types.find((type) => type.id === request.leave_type_id)?.name || `Leave #${request.leave_type_id}`;
  const isSuperAdmin = currentUser?.role === 'hr_admin' && currentUser?.is_superuser === true;

  const superAdminStats = [
    { label: 'Users', value: '28', detail: 'Active accounts' },
    { label: 'Sessions', value: '12', detail: 'Logged in now' },
    { label: 'Invites', value: '4', detail: 'Awaiting activation' },
    { label: 'System health', value: '99.9%', detail: 'Uptime this month' },
  ];

  const roleDistribution = [
    { name: 'Super admin', value: '1', color: 'bg-emerald-500' },
    { name: 'HR managers', value: '2', color: 'bg-sky-500' },
    { name: 'Managers', value: '8', color: 'bg-violet-500' },
    { name: 'Employees', value: '18', color: 'bg-amber-500' },
  ];

  const pendingInvites = [
    { email: 'miriam.kamau@okoa.local', role: 'Manager', status: 'Pending approval' },
    { email: 'edwin.omollo@okoa.local', role: 'Employee', status: 'Awaiting setup' },
    { email: 'sylvia.owino@okoa.local', role: 'Employee', status: 'Awaiting setup' },
  ];

  const systemEvents = [
    { title: 'Password reset completed', detail: '+254712345012 renewed password using OTP', when: '12 mins ago' },
    { title: 'Leave compliance audit', detail: '3 leave requests flagged for review', when: '34 mins ago' },
    { title: 'New team member created', detail: 'Grace Muthoni assigned as HR assistant', when: '1 hr ago' },
  ];

  if (isSuperAdmin) {
    return (
      <AppShell currentUser={currentUser} canApprove={canApprove} onOpenChat={() => setShowChat(true)} onLogout={handleLogout}>
        <main className="leave-main">
          <header className="leave-header">
            <div>
              <p className="leave-kicker">SUPER ADMIN</p>
              <h1>Good day, {currentUser?.name || currentUser?.full_name || 'Administrator'}</h1>
              <p className="leave-muted">Monitor the org, manage access, and keep the leave workflow compliant.</p>
            </div>
            <div className="leave-header-actions">
              <button className="leave-secondary-button" onClick={openProfile}>Profile</button>
              <button className="leave-primary-button" onClick={() => setShowRequestForm(true)}>Create user</button>
            </div>
          </header>

          {message && <div className={`leave-alert ${message.type}`} role="status">{message.text}</div>}

          <section className="leave-stat-grid" id="overview" aria-label="Super admin summary">
            {superAdminStats.map((item) => (
              <div className="leave-stat-card accent-blue" key={item.label}>
                <span>{item.label}</span>
                <strong>{item.value}</strong>
                <small>{item.detail}</small>
              </div>
            ))}
          </section>

          <section className="leave-section" id="users">
            <div className="leave-section-heading">
              <div><p className="leave-kicker">ACCESS</p><h2>Role distribution</h2></div>
            </div>
            <div className="leave-balance-grid">
              {roleDistribution.map((role) => (
                <article className="leave-balance-card" key={role.name}>
                  <div className="profile-summary" style={{ padding: '16px 18px', border: 'none', background: 'transparent' }}>
                    <div className={`topbar-avatar ${role.color}`} style={{ width: '36px', height: '36px', borderRadius: '9999px', display: 'grid', placeItems: 'center' }}>{role.value}</div>
                    <div>
                      <h3>{role.name}</h3>
                      <p>{role.value} assigned</p>
                    </div>
                  </div>
                </article>
              ))}
            </div>
          </section>

          <section className="leave-section" id="invites">
            <div className="leave-section-heading">
              <div><p className="leave-kicker">INVITES</p><h2>Pending user invites</h2></div>
            </div>
            <div className="leave-table-wrap">
              <table className="leave-table">
                <thead>
                  <tr>
                    <th>Email</th>
                    <th>Role</th>
                    <th>Status</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {pendingInvites.map((invite) => (
                    <tr key={invite.email}>
                      <td>{invite.email}</td>
                      <td>{invite.role}</td>
                      <td><span className="leave-status leave-status-pending">{invite.status}</span></td>
                      <td><button className="leave-text-button">Review</button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>

          <section className="leave-section" id="system">
            <div className="leave-section-heading">
              <div><p className="leave-kicker">SYSTEM</p><h2>System health and compliance</h2></div>
            </div>
            <div className="leave-balance-grid">
              <article className="leave-balance-card">
                <h3>System health</h3>
                <strong>99.9%</strong>
                <p>Application uptime</p>
                <small>All core services online</small>
              </article>
              <article className="leave-balance-card">
                <h3>Security events</h3>
                <strong>3</strong>
                <p>Triggered in the last 24 hrs</p>
                <small>1 password reset, 2 failed sign-ins</small>
              </article>
              <article className="leave-balance-card">
                <h3>Workflow checks</h3>
                <strong>12</strong>
                <p>Pending reviews</p>
                <small>Leave policy compliance checks active</small>
              </article>
            </div>
          </section>

          <section className="leave-section" id="activity">
            <div className="leave-section-heading">
              <div><p className="leave-kicker">AUDIT</p><h2>Recent activity</h2></div>
            </div>
            <div className="leave-table-wrap">
              <table className="leave-table">
                <thead>
                  <tr>
                    <th>Event</th>
                    <th>Details</th>
                    <th>When</th>
                  </tr>
                </thead>
                <tbody>
                  {systemEvents.map((event) => (
                    <tr key={event.title}>
                      <td>{event.title}</td>
                      <td>{event.detail}</td>
                      <td>{event.when}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        </main>
      </AppShell>
    );
  }

  return (
    <AppShell currentUser={currentUser} canApprove={canApprove} onOpenChat={() => setShowChat(true)} onLogout={handleLogout}>
      <main className="leave-main">
        <header className="leave-header">
          <div>
            <p className="leave-kicker">EMPLOYEE PORTAL</p>
            <h1>Good day, {currentUser?.name || currentUser?.full_name || 'there'}</h1>
            <p className="leave-muted">Plan your time away and keep your team informed.</p>
          </div>
          <div className="leave-header-actions"><button className="leave-secondary-button" onClick={openProfile}>Edit profile</button><button className="leave-primary-button" onClick={() => setShowRequestForm(true)}>Request leave</button></div>
        </header>

        {message && <div className={`leave-alert ${message.type}`} role="status">{message.text}</div>}

        {loading ? <div className="leave-loading">Loading your leave information...</div> : (
          <>
            <section className="leave-stat-grid" id="overview" aria-label="Leave summary">
              <div className="leave-stat-card accent-blue"><span>Available days</span><strong>{availableDays}</strong><small>Across all leave types</small></div>
              <div className="leave-stat-card accent-teal"><span>Days taken</span><strong>{usedDays}</strong><small>This leave year</small></div>
              <div className="leave-stat-card accent-amber"><span>Pending requests</span><strong>{pendingCount}</strong><small>Awaiting a decision</small></div>
            </section>

            <section className="leave-section" id="balances">
              <div className="leave-section-heading"><div><p className="leave-kicker">YOUR ENTITLEMENT</p><h2>Leave balances</h2></div></div>
              <div className="leave-balance-grid">
                {overview.balances.length === 0 ? <p className="leave-empty">No leave balances have been configured yet.</p> : overview.balances.map((balance) => (
                  <article className="leave-balance-card" key={balance.leave_type_id}>
                    <div><h3>{balance.name}</h3><span>{balance.code}</span></div>
                    <strong>{balance.available_days}</strong>
                    <p>available of {balance.entitled_days} days</p>
                    <div className="leave-progress"><span style={{ width: `${Math.min(100, (Number(balance.used_days) / Math.max(1, Number(balance.entitled_days))) * 100)}%` }} /></div>
                    <small>{balance.used_days} used · {balance.pending_days} pending</small>
                  </article>
                ))}
              </div>
            </section>

            <section className="leave-section" id="requests">
              <div className="leave-section-heading"><div><p className="leave-kicker">TIME AWAY</p><h2>My leave requests</h2></div></div>
              <div className="leave-table-wrap">
                {overview.requests.length === 0 ? <p className="leave-empty">You have not submitted any leave requests.</p> : <table className="leave-table"><thead><tr><th>Leave type</th><th>Dates</th><th>Days</th><th>Status</th><th /></tr></thead><tbody>{overview.requests.map((request) => <tr key={request.id}><td>{request.type_name || request.leave_type_name || leaveTypeName(request)}</td><td>{formatDate(request.start_date)} - {formatDate(request.end_date)}</td><td>{request.days_requested}</td><td><span className={statusClass(request.status)}>{request.status}</span></td><td>{request.status === 'pending' && <button className="leave-text-button" onClick={() => cancelRequest(request.id)}>Cancel</button>}</td></tr>)}</tbody></table>}
              </div>
            </section>

            <section className="leave-section" id="profile">
              <div className="leave-section-heading"><div><p className="leave-kicker">YOUR DETAILS</p><h2>Profile and leave contact</h2></div><button className="leave-text-button" onClick={openProfile}>Edit details</button></div>
              <div className="profile-summary">
                <div className="profile-avatar">{currentUser.profile_photo_url ? <img src={currentUser.profile_photo_url} alt="Profile" /> : (currentUser.name || 'E').charAt(0)}</div>
                <div><h3>{currentUser.employee_name || currentUser.full_name}</h3><p>{currentUser.job_position_title || 'Employee'} · {currentUser.employer || 'Employer not set'}</p><p>{currentUser.department || 'Department not set'}</p></div>
              </div>
            </section>

            {overview.requests.some((request) => request.handover_user_id === currentUser.id) && <section className="leave-section"><div className="leave-section-heading"><div><p className="leave-kicker">HANDOVER</p><h2>Work assigned to you</h2></div></div>{overview.requests.filter((request) => request.handover_user_id === currentUser.id).map((request) => <div className="profile-summary" key={request.id}><div><strong>Leave request #{request.id}</strong><p>{request.handover_statement ? `Current status: ${request.handover_statement}` : 'Please confirm that you have been briefed and accept responsibility.'}</p>{request.handover_report && <p>Report: {request.handover_report}</p>}</div><div className="leave-actions"><button className="leave-primary-button" onClick={() => acceptHandoverRequest(request.id)} disabled={Boolean(request.handover_statement)}>Accept</button><button className="leave-secondary-button" onClick={() => declineHandoverRequest(request.id)} disabled={Boolean(request.handover_statement)}>Decline</button>{!request.handover_statement && <button className="leave-text-button" onClick={() => acknowledge(request.id)}>Use required statement</button>}</div></div>)}</section>}
            {canApprove && <section className="leave-section" id="approvals"><div className="leave-section-heading"><div><p className="leave-kicker">TEAM WORKFLOW</p><h2>Requests needing your decision</h2></div></div><div className="leave-table-wrap">{pendingRequests.length === 0 ? <p className="leave-empty">There are no pending requests to review.</p> : <table className="leave-table"><thead><tr><th>Employee</th><th>Leave</th><th>Dates</th><th>Days</th><th>Actions</th></tr></thead><tbody>{pendingRequests.map((request) => <tr key={request.id}><td>{request.requester_name}</td><td>{request.type_name}</td><td>{formatDate(request.start_date)} - {formatDate(request.end_date)}</td><td>{request.days_requested}</td><td className="leave-actions"><button className="leave-approve" onClick={() => decideRequest(request.id, 'approve')}>Approve</button><button className="leave-reject" onClick={() => decideRequest(request.id, 'reject')}>Reject</button></td></tr>)}</tbody></table>}</div></section>}
          </>
        )}
      </main>

      {showRequestForm && <div className="leave-modal-backdrop" role="presentation"><div className="leave-modal leave-modal-wide" role="dialog" aria-modal="true" aria-labelledby="request-leave-title"><div className="leave-modal-heading"><div><p className="leave-kicker">NEW REQUEST</p><h2 id="request-leave-title">Request leave</h2></div><button className="leave-close" onClick={() => setShowRequestForm(false)} aria-label="Close">×</button></div><form onSubmit={submitRequest}><label>Leave type<select name="leave_type_id" value={form.leave_type_id} onChange={updateForm} required><option value="">Select leave type</option>{overview.types.map((type) => <option value={type.id} key={type.id}>{type.name}</option>)}</select></label><div className="leave-form-row"><label>First day<input type="date" name="start_date" value={form.start_date} onChange={updateForm} required /></label><label>Last day<input type="date" name="end_date" value={form.end_date} onChange={updateForm} required /></label><div className="days-preview"><span>Working days</span><strong>{workingDays()}</strong></div></div><label>Reason<textarea name="reason" value={form.reason} onChange={updateForm} rows="3" placeholder="Add a short reason for your request" required /></label><fieldset className="leave-fieldset"><legend>How we can reach you while away</legend><div className="leave-form-row"><label>Contact phone<input name="contact_phone" value={form.contact_phone} onChange={updateForm} required /></label><label>Contact email<input type="email" name="contact_email" value={form.contact_email} onChange={updateForm} required /></label></div><div className="leave-form-row"><label>Address<input name="address_line1" value={form.address_line1} onChange={updateForm} required /></label><label>City<input name="city" value={form.city} onChange={updateForm} required /></label></div><div className="leave-form-row"><label>Country<input name="country" value={form.country} onChange={updateForm} required /></label><label>Postal code<input name="postal_code" value={form.postal_code} onChange={updateForm} /></label></div></fieldset>{workingDays() > 2 && <fieldset className="leave-fieldset"><legend>Handover</legend><label>Colleague responsible<select name="handover_user_id" value={form.handover_user_id} onChange={updateForm} required><option value="">Select a colleague</option>{chatUsers.map((peer) => <option value={peer.id} key={peer.id}>{peer.name}</option>)}</select></label>{workingDays() > 3 && <label>Full handover report<textarea name="handover_report" value={form.handover_report} onChange={updateForm} rows="4" required placeholder="List work, deadlines, contacts, and risks." /></label>}<p className="leave-helper">The assigned colleague must acknowledge responsibility before the request can be fully handed over.</p></fieldset>}<div className="leave-modal-actions"><button type="button" className="leave-secondary-button" onClick={() => setShowRequestForm(false)}>Back</button><button type="submit" className="leave-primary-button" disabled={submitting}>{submitting ? 'Submitting...' : 'Submit request'}</button></div></form></div></div>}
      {showProfile && <div className="leave-modal-backdrop" role="presentation"><div className="leave-modal leave-modal-wide" role="dialog" aria-modal="true" aria-labelledby="profile-title"><div className="leave-modal-heading"><div><p className="leave-kicker">YOUR DETAILS</p><h2 id="profile-title">Edit profile</h2></div><button className="leave-close" onClick={() => setShowProfile(false)} aria-label="Close">×</button></div><form onSubmit={saveProfile}><label>Profile photo<input type="file" accept="image/jpeg,image/png,image/gif,image/webp" onChange={changeProfilePhoto} /><span className="leave-helper">JPG, PNG, GIF, or WEBP up to 5 MB.</span></label>{profilePhoto && <button type="button" className="leave-text-button" onClick={removeProfilePhoto}>Remove photo</button>}<div className="leave-form-row">{[['employee_name','Employee name'],['job_position_title','Job position title']].map(([name,label]) => <label key={name}>{label}<input name={name} value={profileForm[name] || ''} onChange={(event) => setProfileForm({ ...profileForm, [name]: event.target.value })} required /></label>)}</div><div className="leave-form-row">{[['employer','Employer'],['department','Department']].map(([name,label]) => <label key={name}>{label}<input name={name} value={profileForm[name] || ''} onChange={(event) => setProfileForm({ ...profileForm, [name]: event.target.value })} required /></label>)}</div><fieldset className="leave-fieldset"><legend>Contact and address</legend><div className="leave-form-row">{[['contact_phone','Phone'],['contact_email','Email']].map(([name,label]) => <label key={name}>{label}<input name={name} value={profileForm[name] || ''} onChange={(event) => setProfileForm({ ...profileForm, [name]: event.target.value })} /></label>)}</div><div className="leave-form-row">{[['address_line1','Address'],['address_line2','Address line 2'],['city','City'],['country','Country'],['postal_code','Postal code']].map(([name,label]) => <label key={name}>{label}<input name={name} value={profileForm[name] || ''} onChange={(event) => setProfileForm({ ...profileForm, [name]: event.target.value })} /></label>)}</div></fieldset><div className="leave-modal-actions"><button type="button" className="leave-secondary-button" onClick={() => setShowProfile(false)}>Back</button><button type="submit" className="leave-primary-button">Save profile</button></div></form></div></div>}
      {showChat && <div className="leave-modal-backdrop" role="presentation"><div className="leave-modal chat-modal" role="dialog" aria-modal="true" aria-labelledby="chat-title"><div className="leave-modal-heading"><div><p className="leave-kicker">TEAM CHAT</p><h2 id="chat-title">Messages</h2></div><button className="leave-close" onClick={() => setShowChat(false)} aria-label="Close">×</button></div><label>Chat with<select value={chatPeer} onChange={(event) => setChatPeer(event.target.value)}><option value="">Select a colleague</option>{chatUsers.map((peer) => <option value={peer.id} key={peer.id}>{peer.name}</option>)}</select></label><div className="chat-messages">{chatMessages.length === 0 ? <p className="leave-empty">No messages yet.</p> : chatMessages.map((item) => <div className={`chat-message ${item.sender_id === currentUser.id ? 'mine' : ''}`} key={item.id}><span>{item.sender_name}</span><p>{item.body}</p></div>)}</div><form className="chat-compose" onSubmit={submitChat}><input value={chatBody} onChange={(event) => setChatBody(event.target.value)} placeholder="Write a message" maxLength="2000" /><button className="leave-primary-button" type="submit">Send</button></form></div></div>}
    </AppShell>
  );
};

export default LeaveDashboard;
